"""Português — Alcorão (quran_001 … quran_080)."""

T = {
"quran_001": ("Como se chama o primeiro capítulo (surata) do Alcorão?", ["Al-Fatiha", "Al-Baqara", "Al-Ikhlas", "An-Nas"], "Al-Fatiha, «A Abertura», é o primeiro capítulo do Alcorão."),
"quran_002": ("Quantos capítulos (suratas) tem o Alcorão?", ["114", "99", "100", "120"], "O Alcorão é composto por 114 suratas."),
"quran_003": ("Qual é a surata mais longa do Alcorão?", ["Al-Baqara", "Al-Fatiha", "Al-Kawthar", "Al-Asr"], "Al-Baqara é a surata mais longa do Alcorão, com 286 versículos."),
"quran_004": ("Qual é a surata mais curta do Alcorão?", ["Al-Kawthar", "Al-Ikhlas", "Al-Asr", "An-Nasr"], "Al-Kawthar, com 3 versículos, é a surata mais curta do Alcorão."),
"quran_005": ("Em que língua foi revelado o Alcorão?", ["Árabe", "Aramaico", "Hebraico", "Persa"], "O Alcorão afirma explicitamente que foi revelado em língua árabe."),
"quran_006": ("Como se chama a surata 19, com o nome da mãe de Isa?", ["Maryam", "Yusuf", "Al-Kahf", "Ta-Ha"], "A surata 19 do Alcorão chama-se Maryam, pela mãe do profeta Isa."),
"quran_007": ("Como se chama um capítulo do Alcorão?", ["Uma surata", "Um hadith", "Um juz'", "Um tafsir"], "O Alcorão divide-se em capítulos chamados suratas."),
"quran_008": ("Como se chama um versículo do Alcorão?", ["Uma ayah", "Uma surata", "Um hadith", "Um ruku'"], "Cada versículo do Alcorão chama-se ayah, que significa «sinal»."),
"quran_009": ("Que surata é recitada obrigatoriamente em cada unidade (rak'a) da oração?", ["Al-Fatiha", "Al-Ikhlas", "Al-Kawthar", "Al-Fil"], "Recitar Al-Fatiha é um pilar da oração, segundo um hadith autêntico."),
"quran_010": ("A quem foi revelado o Alcorão?", ["Ao Profeta Muhammad ﷺ", "Ao profeta Musa", "Ao profeta Isa", "Ao profeta Dawud"], "O Alcorão foi revelado ao Profeta Muhammad ﷺ, através do anjo Jibril."),
"quran_011": ("Como se chama o famoso versículo 255 da surata Al-Baqara?", ["Ayat al-Kursi (o Versículo do Trono)", "Ayat an-Nur", "Ayat as-Siyam", "Ayat ad-Dayn"], "O versículo 2:255, Ayat al-Kursi, descreve a grandeza de Allah: «Allah, não há deus senão Ele, o Vivente…»."),
"quran_012": ("Que surata não começa com «Bismillah ir-Rahman ir-Rahim»?", ["At-Tawba", "Al-Fatiha", "Ya-Sin", "Al-Kahf"], "At-Tawba (surata 9) é a única surata que não começa com a basmala."),
"quran_013": ("Qual é o tema do versículo mais longo do Alcorão (2:282)?", ["Registar as dívidas por escrito", "A peregrinação", "O jejum", "A herança"], "O versículo mais longo do Alcorão ensina a escrever as dívidas e a tomar testemunhas: a honestidade fica protegida."),
"quran_014": ("Com que palavra começam os primeiríssimos versículos revelados do Alcorão?", ["Iqra' (Lê!)", "Qul (Diz!)", "Sabbih (Glorifica!)", "Kutiba (Foi prescrito)"], "Os primeiros versículos revelados começam com «Iqra'»: «Lê, em nome do teu Senhor que criou»."),
"quran_015": ("Segundo o Alcorão, a Noite de Al-Qadr é melhor do que quantos meses?", ["Mil meses", "Cem meses", "Doze meses", "Quarenta meses"], "«A Noite de Al-Qadr é melhor do que mil meses»: uma noite de Ramadão vale mais do que uma vida inteira de adoração."),
"quran_016": ("Como se chamam as duas últimas suratas, Al-Falaq e An-Nas, recitadas para procurar proteção?", ["Al-Mu'awwidhatan (as duas protetoras)", "Az-Zahrawan", "Al-Mufassal", "As-Sab' at-Tiwal"], "Al-Falaq e An-Nas chamam-se «al-mu'awwidhatan»: são recitadas para procurar a proteção de Allah."),
"quran_017": ("Em quantas partes (juz') se divide tradicionalmente o Alcorão?", ["30", "10", "60", "114"], "O Alcorão divide-se em 30 juz', o que ajuda a completá-lo num mês, por exemplo no Ramadão."),
"quran_018": ("Quantos versículos tem a surata Al-Fatiha?", ["7", "3", "10", "14"], "Al-Fatiha tem sete versículos, recitados em cada unidade da oração."),
"quran_019": ("Que surata tem o nome de um metal?", ["Al-Hadid (O Ferro)", "An-Nur (A Luz)", "Ar-Ra'd (O Trovão)", "Ad-Dukhan (O Fumo)"], "A surata 57 chama-se Al-Hadid: «Fizemos descer o ferro, no qual há grande força e benefícios para as pessoas»."),
"quran_020": ("Que história chama o Alcorão «a mais bela das histórias»?", ["A história de Yusuf", "A história de Nuh", "A história da gente da caverna", "A história do elefante"], "«Relatamos-te a mais bela das histórias»: assim começa a história de Yusuf."),
"quran_021": ("Quantos versículos tem Al-Baqara, a surata mais longa?", ["286", "114", "200", "365"], "Al-Baqara tem 286 versículos: a surata mais longa do Alcorão."),
"quran_022": ("Que surata curta proclama: «Diz: Ele é Allah, Único»?", ["Al-Ikhlas", "Al-Falaq", "An-Nas", "Al-Kawthar"], "Al-Ikhlas proclama a perfeita unicidade de Allah em quatro versículos."),
"quran_023": ("Ao longo de aproximadamente quantos anos foi revelado o Alcorão?", ["23 anos", "1 ano", "10 anos", "40 anos"], "O Alcorão foi revelado gradualmente durante cerca de 23 anos, em Meca e depois em Medina."),
"quran_024": ("Segundo o Alcorão, qual foi a primeira Casa estabelecida para as pessoas adorarem Allah?", ["A Ka'ba, em Bakka (Meca)", "A mesquita de Quba", "Bayt al-Maqdis", "A mesquita do Profeta ﷺ"], "«A primeira Casa estabelecida para a humanidade é a de Bakka, abençoada…»: a Ka'ba em Meca."),
"quran_025": ("Que surata tem o nome do elefante?", ["Al-Fil", "An-Nahl", "An-Naml", "Al-Baqara"], "A surata 105, Al-Fil («O Elefante»), recorda o exército de elefantes de Abraha, detido diante de Meca."),
"quran_026": ("A surata An-Nahl tem o nome de que inseto?", ["A abelha", "A formiga", "A aranha", "A mosca"], "An-Nahl significa «as abelhas»; nela Allah inspira a abelha a construir as suas casas (16:68)."),
"quran_027": ("Que surata tem o nome da formiga?", ["An-Naml", "An-Nahl", "Al-Ankabut", "Al-An'am"], "An-Naml («As Formigas», surata 27) conta a formiga que avisou as companheiras quando o exército de Sulayman se aproximava."),
"quran_028": ("Na surata Al-Ankabut, com que compara o Alcorão os que tomam protetores fora de Allah?", ["Com a aranha que constrói uma casa frágil", "Com a abelha que constrói a colmeia", "Com a formiga que armazena comida", "Com o cão que arfa"], "«A mais frágil das casas é a casa da aranha» (29:41), daí o nome da surata."),
"quran_029": ("A surata Al-Baqara tem o nome de que animal?", ["A vaca", "O camelo", "O cavalo", "A ovelha"], "Al-Baqara («A Vaca») recorda a vaca que os Filhos de Israel deviam sacrificar (2:67)."),
"quran_030": ("O que significa o título da surata 6, Al-An'am?", ["O gado", "Os pássaros", "Os jardins", "As estrelas"], "Al-An'am significa «o gado»; a surata refuta as regras inventadas pelos pagãos sobre os animais."),
"quran_031": ("Que versículo se repete muitas vezes na surata Ar-Rahman?", ["«Qual dos favores do vosso Senhor negareis?»", "«Allah é o Maior»", "«Diz: Ele é Allah, Único»", "«Louvado seja Allah»"], "Este refrão («Fa-bi-ayyi ala'i rabbikuma tukadhdhiban») repete-se 31 vezes na surata 55."),
"quran_032": ("Segundo a surata Al-Kahf, quanto tempo dormiu a Gente da Caverna?", ["Trezentos anos, e mais nove", "Cem anos", "Quarenta anos", "Mil anos"], "«Permaneceram na sua caverna trezentos anos, e acrescentaram nove» (18:25)."),
"quran_033": ("Que animal acompanhava a Gente da Caverna?", ["Um cão", "Um gato", "Um burro", "Uma cabra"], "«O seu cão estendia as patas dianteiras à entrada» (18:18)."),
"quran_034": ("Contra que povos construiu Dhul-Qarnayn uma barreira, segundo Al-Kahf?", ["Ya'juj e Ma'juj (Gog e Magog)", "'Ad e Thamud", "Os romanos", "Os persas"], "Um povo pediu-lhe proteção contra Ya'juj e Ma'juj; ergueu uma muralha de ferro e cobre (18:94-96)."),
"quran_035": ("Que versículo começa com «Allah é a Luz dos céus e da terra»?", ["O Versículo da Luz (An-Nur 24:35)", "O Versículo do Trono", "O Versículo da Dívida", "O Versículo da Caverna"], "«Ayat an-Nur» compara a Sua luz a um nicho onde brilha uma lâmpada (24:35)."),
"quran_036": ("Segundo um hadith de al-Bukhari, que surata equivale a um terço do Alcorão?", ["Al-Ikhlas", "Al-Fatiha", "Ya-Sin", "Al-Kahf"], "O Profeta ﷺ disse de «Qul huwa Allahu ahad» que «equivale a um terço do Alcorão»."),
"quran_037": ("Que versículo apontou o Profeta ﷺ como o maior do Alcorão, segundo Sahih Muslim?", ["O Versículo do Trono (Ayat al-Kursi)", "O primeiro versículo de Al-Fatiha", "O último versículo de Al-Baqara", "O Versículo da Luz"], "Perguntou a Ubayy ibn Ka'b qual era o maior versículo; Ubayy respondeu Ayat al-Kursi, e o Profeta ﷺ felicitou-o."),
"quran_038": ("Que inimigo do Profeta ﷺ é nomeado na surata Al-Masad?", ["Abu Lahab", "Abu Jahl", "Abu Sufyan", "Al-Walid"], "«Pereçam as mãos de Abu Lahab!» (111:1): este tio do Profeta ﷺ combateu-o abertamente."),
"quran_039": ("Como termina a surata Al-Kafirun?", ["«Para vós a vossa religião, e para mim a minha religião»", "«Allah é o Maior»", "«E não há ninguém igual a Ele»", "«Do mal do invejoso»"], "«Lakum dinukum wa liya din» (109:6) afirma a clara separação entre o islão e a idolatria."),
"quran_040": ("De que trata a surata An-Nasr?", ["Do auxílio de Allah e das pessoas a entrarem em massa na religião", "Da criação do céu", "Do jejum do Ramadão", "Da história de Yusuf"], "«Quando chegar o auxílio de Allah e a vitória, e vires as pessoas entrarem em massa na religião de Allah» (110:1-2)."),
"quran_041": ("Segundo a surata Al-Asr, quem se salva da perdição?", ["Os que creem, praticam o bem e recomendam uns aos outros a verdade e a paciência", "Os ricos", "Os fortes", "Os que viajam"], "«O homem está em perdição, exceto os que creem, praticam o bem e recomendam uns aos outros a verdade e a paciência» (103:2-3)."),
"quran_042": ("Na surata Al-Ma'un, o que faz «aquele que nega o Juízo»?", ["Repele o órfão e não incentiva a alimentar o pobre", "Destrói mesquitas", "Recusa-se a viajar", "Mente sobre a sua riqueza"], "«É aquele que repele o órfão e não incentiva a alimentar o pobre» (107:2-3)."),
"quran_043": ("Segundo os primeiros versículos revelados (Al-Alaq), de que criou Allah o homem?", ["De um coágulo aderente (alaq)", "De luz", "De fogo", "De vento"], "«Lê, em nome do teu Senhor que criou, que criou o homem de um coágulo aderente» (96:1-2)."),
"quran_044": ("A que se refere a expressão corânica «os sete versículos repetidos» (as-sab' al-mathani)?", ["A Al-Fatiha", "Às sete suratas mais longas", "A Ayat al-Kursi", "Aos sete últimos versículos do Alcorão"], "«Demos-te sete dos repetidos e o Alcorão grandioso» (15:87): Al-Fatiha, recitada em cada rak'a."),
"quran_045": ("O que significa «Al-Furqan», um dos nomes do Alcorão?", ["O Critério (entre verdade e falsidade)", "A Luz", "A Lembrança", "A Cura"], "«Bendito seja Aquele que fez descer o Furqan sobre o Seu servo» (25:1): o Livro que separa a verdade da falsidade."),
"quran_046": ("Por que jura Allah no início da surata At-Tur?", ["Pelo Monte (Tur)", "Pelo sol", "Pela figueira", "Pela noite"], "«Pelo Monte! E por um Livro escrito…» (52:1-2): o Tur é a montanha onde Musa recebeu a revelação."),
"quran_047": ("O que significa «An-Najm», título da surata 53?", ["A estrela", "A lua", "O sol", "A aurora"], "«Pela estrela quando declina!» (53:1)."),
"quran_048": ("Segundo a surata Al-Qadr, quem desce na Noite do Decreto?", ["Os anjos e o Espírito (Jibril)", "Os profetas", "Os génios", "Os ventos"], "«Os anjos e o Espírito descem nela com a permissão do seu Senhor» (97:4)."),
"quran_049": ("Segundo o Alcorão, o que é o Alcorão para os crentes?", ["Uma cura e uma misericórdia", "Apenas um poema", "Um livro de história", "Um calendário"], "«Fazemos descer do Alcorão o que é cura e misericórdia para os crentes» (17:82)."),
"quran_050": ("Que desafio lança o Alcorão a quem duvida da sua origem divina?", ["Produzir uma única surata semelhante", "Recitar todo o Alcorão de cor", "Traduzir o Alcorão", "Construir uma mesquita"], "«Se duvidais do que revelámos, trazei uma surata semelhante» (2:23)."),
"quran_051": ("Que surata se chama «Umm al-Qur'an» (a Mãe do Alcorão)?", ["Al-Fatiha", "Al-Baqara", "Ya-Sin", "Al-Ikhlas"], "O Profeta ﷺ disse: «Umm al-Qur'an são os sete versículos repetidos e o Alcorão grandioso»."),
"quran_052": ("O que é uma surata «mequense» (makkiyya)?", ["Uma surata revelada antes da Hégira", "Uma surata revelada em Medina", "Uma surata sobre a Ka'ba", "Uma surata muito curta"], "Os sábios classificam as suratas pelo período: antes da emigração para Medina (mequenses) ou depois (medinenses)."),
"quran_053": ("Quantas suratas começam com as letras «Alif, Lam, Mim»?", ["Seis", "Duas", "Dez", "Uma"], "Al-Baqara, Al Imran, Al-Ankabut, Ar-Rum, Luqman e As-Sajda começam com «Alif, Lam, Mim»."),
"quran_054": ("Como se chamam as letras isoladas que abrem algumas suratas (Alif Lam Mim, Ya Sin, Qaf…)?", ["As letras separadas (al-huruf al-muqatta'a)", "Os versículos ab-rogados", "As letras solares", "As letras do tajwid"], "Vinte e nove suratas começam com estas letras, cujo sentido pleno só Allah conhece."),
"quran_055": ("Que surata tem o nome do Profeta Muhammad ﷺ?", ["A surata 47, Muhammad", "A surata 1, Al-Fatiha", "A surata 36, Ya-Sin", "A surata 112, Al-Ikhlas"], "A surata 47 chama-se «Muhammad»; menciona o seu nome no versículo 2."),
"quran_056": ("Qual é o primeiro conselho de Luqman ao seu filho, citado no Alcorão?", ["Não associar nada a Allah", "Estudar as estrelas", "Tornar-se comerciante", "Viajar para longe"], "«Meu filho, não associes nada a Allah; a associação é uma injustiça enorme» (31:13)."),
"quran_057": ("Por que outro nome é conhecida a surata At-Tawba?", ["Bara'a (a Desvinculação)", "An-Nur", "Al-Anfal", "Al-Fath"], "A sua primeira palavra é «Bara'a»: uma declaração de desvinculação de Allah e do Seu Mensageiro em relação aos idólatras (9:1)."),
"quran_058": ("Que surata começa com as duas letras «Ya, Sin»?", ["Ya-Sin (surata 36)", "Ta-Ha", "Qaf", "Sad"], "A surata 36 começa com «Ya-Sin. Pelo Alcorão sábio!»."),
"quran_059": ("O que significa «Al-Mulk», título da surata 67?", ["A Soberania / o Reino", "A Luz", "A Viagem", "A Vitória"], "«Bendito seja Aquele em cuja mão está a Soberania (al-Mulk)» (67:1)."),
"quran_060": ("Qual é a última surata do Alcorão?", ["An-Nas", "Al-Falaq", "Al-Ikhlas", "Al-Fatiha"], "An-Nas («Os Homens»), surata 114, encerra o Alcorão: «Diz: refugio-me no Senhor dos homens»."),
"quran_061": ("Como começa a surata Al-Falaq?", ["«Diz: refugio-me no Senhor da alvorada»", "«Diz: Ele é Allah, Único»", "«Pelo tempo!»", "«Louvado seja Allah»"], "«Qul a'udhu bi-rabbi-l-falaq» (113:1): Al-Falaq significa a alvorada."),
"quran_062": ("Que duas colinas nomeia o Alcorão entre os «ritos de Allah»?", ["As-Safa e Al-Marwa", "Uhud e Thawr", "Arafat e Mina", "Hira e Abu Qubays"], "«As-Safa e Al-Marwa estão entre os ritos de Allah» (2:158): entre elas faz-se o sa'y da peregrinação."),
"quran_063": ("Qual é a única mulher mencionada pelo nome no Alcorão?", ["Maryam", "Khadija", "Asiya", "Hajar"], "Maryam, mãe de Isa, é nomeada em várias suratas, e uma surata inteira tem o seu nome."),
"quran_064": ("Qual é o único companheiro do Profeta ﷺ nomeado no Alcorão?", ["Zayd ibn Haritha", "Abu Bakr", "Umar", "Ali"], "«Quando Zayd terminou a sua relação com ela…» (33:37): Zayd, o liberto do Profeta ﷺ, é o único companheiro nomeado."),
"quran_065": ("Quem eram Harut e Marut, mencionados na surata Al-Baqara?", ["Dois anjos enviados a Babilónia", "Dois profetas", "Dois reis do Egito", "Dois companheiros"], "«…o que foi feito descer aos dois anjos Harut e Marut em Babilónia» (2:102): avisavam que a magia era uma prova."),
"quran_066": ("Segundo o Alcorão, quem é o mais nobre diante de Allah?", ["O mais piedoso", "O mais rico", "O mais forte", "O mais famoso"], "«O mais nobre de vós diante de Allah é o mais piedoso» (49:13)."),
"quran_067": ("A que se refere «Al-Waqi'a», título da surata 56?", ["Ao Acontecimento inevitável (o Dia da Ressurreição)", "À caravana", "À formiga", "À viagem noturna"], "«Quando acontecer o Acontecimento…» (56:1): a surata descreve os três grupos do Último Dia."),
"quran_068": ("Por que objeto jura Allah no início da surata Al-Qalam?", ["Pelo cálamo", "Pela espada", "Pela balança", "Pela lâmpada"], "«Nun. Pelo cálamo e pelo que escrevem!» (68:1)."),
"quran_069": ("Como começa a surata Al-Fajr?", ["Com um juramento pela aurora e dez noites", "Com um juramento pela figueira", "Com uma história de Yusuf", "Apenas com a basmala"], "«Pela aurora! E pelas dez noites!» (89:1-2)."),
"quran_070": ("Por que astro jura Allah no início da surata Ash-Shams?", ["Pelo sol", "Apenas pela lua", "Pelas estrelas", "Pelos planetas"], "«Pelo sol e a sua claridade!» (91:1); Ash-Shams significa «o sol»."),
"quran_071": ("Que surata começa com: «Passou para o homem um período de tempo em que não era nada mencionável?»", ["Al-Insan (surata 76)", "Al-Kahf", "Al-Hajj", "Al-Fatiha"], "Al-Insan («O Homem»), também chamada Ad-Dahr, recorda que o homem não era nada antes da sua criação (76:1)."),
"quran_072": ("Segundo o Alcorão, para que tornou Allah o Alcorão fácil?", ["Para a lembrança e a memorização", "Para o comércio", "Para a tradução", "Para o esquecimento"], "«Tornámos o Alcorão fácil de recordar; há quem reflita?» (54:17), repetido quatro vezes na surata."),
"quran_073": ("Que sinal menciona a surata Al-Qamar logo no seu primeiro versículo?", ["A lua fendeu-se", "O sol apagou-se", "O mar abriu-se", "A montanha falou"], "«A Hora aproxima-se e a lua fendeu-se» (54:1): um sinal mostrado aos mequenses."),
"quran_074": ("Porque foi o Alcorão revelado gradualmente e não de uma só vez, segundo o próprio Alcorão?", ["Para firmar o coração do Profeta ﷺ", "Porque era longo demais", "Para o esconder dos inimigos", "Por causa das viagens"], "«Assim, para firmar com ele o teu coração, e recitámo-lo com esmero» (25:32)."),
"quran_075": ("Que suratas recitava o Profeta ﷺ todas as noites nas mãos antes de dormir, segundo Aisha?", ["Al-Ikhlas, Al-Falaq e An-Nas", "Al-Fatiha e Al-Baqara", "Ya-Sin e Al-Mulk", "Al-Kahf e Maryam"], "Soprava nas mãos recitando as três suratas «Qul», e depois passava-as pelo corpo, três vezes."),
"quran_076": ("Como se chama a prostração que se faz ao recitar certos versículos do Alcorão?", ["A prostração da recitação (sujud at-tilawa)", "A prostração do esquecimento", "A prostração de agradecimento", "O ruku'"], "O Alcorão contém versículos de prostração, como o último de Al-Alaq: «prostra-te e aproxima-te» (96:19)."),
"quran_077": ("Como se chama a ciência das regras da correta pronúncia do Alcorão?", ["O tajwid", "O tafsir", "O fiqh", "A sira"], "O tajwid ensina a pronunciar cada letra a partir do seu ponto de articulação, com as suas qualidades."),
"quran_078": ("Como se chama a pessoa que memorizou todo o Alcorão?", ["Um hafiz", "Um imã", "Um muezim", "Um mufti"], "Hafiz significa «aquele que guarda»: traz o Alcorão inteiro na memória."),
"quran_079": ("Como se chama o exemplar escrito do Alcorão?", ["Um mushaf", "Um hadith", "Um juz'", "Um minbar"], "O mushaf é o Alcorão reunido entre duas capas; um juz' é uma das suas trinta partes."),
"quran_080": ("Em que surata aparece a basmala duas vezes?", ["An-Naml", "Al-Fatiha", "At-Tawba", "Al-Baqara"], "Além do seu início, An-Naml cita a basmala no começo da carta de Sulayman à rainha de Sabá (27:30)."),
}
